float diamond_rot_speed = 0.0;

mat2 rot(float r){
    float i = sin(r);
    float j = cos(r);

    return  mat2(j, -i, i, j);
}

float diamond(vec3 p){
    p = abs(p);
    return (
        p.x +
        p.y +
        p.z - 1.0
    )*0.5;
}

float map(vec3 p){
    // spheres
    vec3 s1_r = p;
    float s1 = length(s1_r) - 1.0;

    // Diamond
    vec3 d_r = p;

    float d_rot_speed = iTime * 0.5;

    d_r.xz *= rot((d_rot_speed));
    d_r.zy *= rot(sin(d_rot_speed * 0.1));

    float d = diamond(d_r);

    // displacement
    vec3 disp_r = p;

    float disp = (cos(5. * disp_r.x) * cos(5. * disp_r.y) * cos(5. * disp_r.z)) * 2.;
    float disp_mix = (iTime * 0.005);

    d = mix(d, disp, disp_mix);

    // Output map
    float mix_value = min(0.9, (iTime * 0.02));

    float out_map = 0.;

    out_map = mix(d, s1, mix_value);

    return out_map;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float z_cam = -10. + (iTime * 0.2);

    vec3 origin = vec3(0,0,z_cam);

    vec3 dir = normalize(vec3(uv,2.0));
    vec3 col = vec3(0);

    float t = 0.0;

    int steps = 100;
    for (int i=0; i < steps; i++){
        vec3 pos = origin + dir * t;

        float d = map(pos);

        t += d;

        col = vec3(i) / float(steps);
        col *= col * ((iTime / 10.));

        if (d < .000001) break;
        if (t > 40.0) break;
    }


    fragColor = vec4(col,0.);
}
